export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

export function splitAuthority(a) {
  if (a === undefined) return undefined
  let userinfo
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const from = a.lastIndexOf(']') + 1
  const c = a.indexOf(':', from)
  let host = a, port
  if (c >= 0) { host = a.slice(0, c); port = a.slice(c + 1) }
  return { userinfo, host, port }
}

export function removeDots(path) {
  let inp = path, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const ch = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(ch) ? ch : '%' + h.toUpperCase()
  })
}
const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class UriError extends Error {}

export function normalize(r) {
  const au = splitAuthority(r.authority)
  const parts = [
    ['userinfo', au && au.userinfo], ['host', au && au.host],
    ['path', r.path], ['query', r.query], ['fragment', r.fragment],
  ]
  for (const [name, v] of parts) {
    if (v !== undefined && /%(?![0-9A-Fa-f]{2})/.test(v)) {
      throw new UriError(`the ${name} has a truncated percent-encoding`)
    }
  }
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let out = scheme === undefined ? '' : scheme + ':'
  let path = r.path
  if (au) {
    out += '//'
    if (au.userinfo !== undefined) out += pct(au.userinfo) + '@'
    out += lower(pct(au.host))
    let port = au.port
    if (port === '' || (scheme in DEFAULT && port === DEFAULT[scheme])) port = undefined
    if (port !== undefined) out += ':' + pct(port)
  }
  path = removeDots(pct(path))
  if (au && path === '') path = '/'
  out += path
  if (r.query !== undefined) out += '?' + pct(r.query)
  if (r.fragment !== undefined) out += '#' + pct(r.fragment)
  return out
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    t.fragment = ref.fragment
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      t.query = ref.query
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let p
        if (base.authority !== undefined && base.path === '') p = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          p = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(p)
      }
    }
  }
  return t
}
