cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'
import { parse, normalize, resolve, UriError } from './uri.js'

const mode = process.argv.length === 3 ? process.argv[2] : undefined
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'normalize' && mode !== 'resolve') fail('error: usage: cli.js normalize|resolve')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const out = []
lines.forEach((line, idx) => {
  const n = idx + 1
  try {
    if (mode === 'normalize') out.push(normalize(parse(line)))
    else {
      const sp = line.indexOf(' ')
      if (sp < 0) fail(`error: line ${n}: expected a base and a reference`)
      const base = parse(line.slice(0, sp))
      if (base.scheme === undefined) fail(`error: line ${n}: the base has no scheme`)
      out.push(normalize(resolve(base, parse(line.slice(sp + 1)))))
    }
  } catch (e) {
    if (e instanceof UriError) fail(`error: line ${n}: ${e.message}`)
    throw e
  }
})
process.stdout.write(out.map((l) => l + '\n').join(''))
EOF
