import { readFileSync } from 'node:fs'

class Fail extends Error {}

function parse(s) {
  let m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at < 0 ? undefined : a.slice(0, at)
  const rest = a.slice(at + 1)
  const colon = rest.indexOf(':', rest.lastIndexOf(']') + 1)
  if (colon < 0) return { userinfo, host: rest, port: undefined }
  return { userinfo, host: rest.slice(0, colon), port: rest.slice(colon + 1) }
}

function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s, name) {
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new Fail(`the ${name} has a truncated percent-encoding`)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function recompose(t) {
  let r = ''
  if (t.scheme !== undefined) r += t.scheme + ':'
  if (t.authority !== undefined) r += '//' + t.authority
  r += t.path
  if (t.query !== undefined) r += '?' + t.query
  if (t.fragment !== undefined) r += '#' + t.fragment
  return r
}

function normalize(t) {
  const scheme = t.scheme === undefined ? undefined : lower(t.scheme)
  let authority
  let path = t.path
  let a
  if (t.authority !== undefined) a = splitAuthority(t.authority)
  // validate in order: path, userinfo, host, query, fragment
  path = pct(path, 'path')
  if (a) {
    if (a.userinfo !== undefined) a.userinfo = pct(a.userinfo, 'userinfo')
    a.host = lower(pct(a.host, 'host'))
  }
  const query = t.query === undefined ? undefined : pct(t.query, 'query')
  const fragment = t.fragment === undefined ? undefined : pct(t.fragment, 'fragment')
  if (a) {
    let port = a.port
    if (port === '' || (scheme !== undefined && DEFAULT[scheme] === port)) port = undefined
    authority = (a.userinfo !== undefined ? a.userinfo + '@' : '') + a.host + (port !== undefined ? ':' + port : '')
  }
  path = removeDots(path)
  if (authority !== undefined && path === '') path = '/'
  return recompose({ scheme, authority, path, query, fragment })
}

function resolve(base, ref) {
  const b = parse(base)
  const r = parse(ref)
  const t = {}
  if (r.scheme !== undefined) {
    Object.assign(t, r, { path: removeDots(r.path) })
  } else if (r.authority !== undefined) {
    Object.assign(t, r, { scheme: b.scheme, path: removeDots(r.path) })
  } else {
    t.scheme = b.scheme
    t.authority = b.authority
    t.fragment = r.fragment
    if (r.path === '') {
      t.path = b.path
      t.query = r.query !== undefined ? r.query : b.query
    } else {
      if (r.path.startsWith('/')) t.path = removeDots(r.path)
      else {
        let merged
        if (b.authority !== undefined && b.path === '') merged = '/' + r.path
        else {
          const i = b.path.lastIndexOf('/')
          merged = i < 0 ? r.path : b.path.slice(0, i + 1) + r.path
        }
        t.path = removeDots(merged)
      }
      t.query = r.query
    }
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((line, idx) => {
      try {
        if (args[0] === 'normalize') out.push(normalize(parse(line)))
        else {
          const sp = line.indexOf(' ')
          if (sp < 0) throw new Fail('expected a base and a reference')
          const base = line.slice(0, sp)
          if (parse(base).scheme === undefined) throw new Fail('the base has no scheme')
          out.push(normalize(resolve(base, line.slice(sp + 1))))
        }
      } catch (e) {
        if (e instanceof Fail) throw new Fail(`line ${idx + 1}: ${e.message}`)
        throw e
      }
    })
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}

main()
