export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = [] // Map name -> votes per round
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const pick = b.prefs.find((p) => continuing.has(p))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    history.push(votes)
    const listing = [...votes.entries()].sort((a, b) =>
      a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)
    const round = { listing: listing.map(([n, v]) => [n, String(v)]), exhausted: String(total - active), eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [n, v] of listing) {
      if (v * 2n > active) return { rounds, winner: n }
    }
    let min = null
    for (const v of votes.values()) if (min === null || v < min) min = v
    let tied = [...votes.keys()].filter((c) => votes.get(c) === min)
    for (let r = 0; tied.length > 1 && r < history.length; r++) {
      let m = null
      for (const c of tied) { const v = history[r].get(c); if (m === null || v < m) m = v }
      const keep = tied.filter((c) => history[r].get(c) === m)
      if (keep.length < tied.length) { tied = keep; r = -1 }
    }
    const out = tied.reduce((a, b) => (b > a ? b : a))
    round.eliminated = out
    continuing.delete(out)
  }
}
