{"command":"cat > src/cli.js <<'EOF'
#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'replay' && mode[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function parseInt_(text, field, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

const policies = new Map()
const routes = new Map()
const events = []
let lastTick = null

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    try {
      handle(line.split(/\s+/))
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
}

function handle(t) {
  const word = t[0]
  const decl = word === 'bucket' || word === 'window' || word === 'route'
  if (!decl && word !== 'event') throw new Fail(`unknown directive ${word}`)
  if (decl && lastTick !== null) throw new Fail('declarations must come before the first event')
  if (word === 'bucket') {
    if (t.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
    if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
    const capacity = parseInt_(t[2], 'capacity', 1)
    const refill = parseInt_(t[3], 'refill', 0)
    const per = parseInt_(t[4], 'per', 1)
    if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
    policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per, states: new Map() })
  } else if (word === 'window') {
    if (t.length !== 4) throw new Fail('expected window <name> <limit> <span>')
    if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
    const limit = parseInt_(t[2], 'limit', 0)
    const span = parseInt_(t[3], 'span', 1)
    if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
    policies.set(t[1], { name: t[1], kind: 'window', limit, span, states: new Map() })
  } else if (word === 'route') {
    if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
    if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
    if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
    const list = []
    for (const n of t.slice(2)) {
      if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
      list.push(policies.get(n))
    }
    routes.set(t[1], list)
  } else {
    if (t.length !== 3) throw new Fail('expected event <tick> <key>')
    const tick = parseInt_(t[1], 'tick', 0)
    if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
    if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${t[1]} is before tick ${lastTick}`)
    lastTick = tick
    events.push({ tick, tickText: t[1], key: t[2] })
  }
