#!/usr/bin/env node
/**
 * `node src/cli.js values` prints the value of every cell in the sheet read
 * from standard input; `deps` prints the cells each one names.
 */
import { readFileSync } from 'node:fs'
import { parseFormula } from './formula.js'
import { evaluateSheet, formatValue } from './evaluate.js'
import { cellKey, parseAddress, addressText, collectRefs } from './address.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') continue
  const m = /^[^ \t]*/.exec(line)[0]
  const content = line.slice(m.length).replace(/^[ \t]+/, '')
  const addr = parseAddress(m)
  if (!addr) fail(`error: line ${i + 1}: invalid cell address ${m}`)
  const key = cellKey(addr)
  if (cells.has(key)) fail(`error: line ${i + 1}: cell ${addressText(addr)} is declared twice`)
  cells.set(key, { addr, content })
}

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const sorted = [...cells.values()].sort((a, b) => a.addr.col - b.addr.col || a.addr.row - b.addr.row)
let out = ''
if (mode === 'values') {
  const values = evaluateSheet(cells)
  for (const c of sorted) out += `${addressText(c.addr)}=${formatValue(values.get(cellKey(c.addr)))}\n`
} else {
  for (const c of sorted) {
    let text = addressText(c.addr) + ':'
    if (c.content[0] === '=') {
      const tree = parseFormula(c.content.slice(1))
      if (tree) for (const a of collectRefs(tree)) text += ' ' + addressText(a)
    }
    out += text + '\n'
  }
}
process.stdout.write(out)
