cat > src/merge.js <<'EOF'
function changes(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j })
  }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush(); i++; j++; bs = i; ss = j
    } else if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  flush()
  return out
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mode, mine, base, theirs) {
  const all = [
    ...changes(base, mine).map(c => ({ ...c, side: 0 })),
    ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
  ].sort((a, b) => a.bs - b.bs || a.side - b.side)
  const sides = [mine, theirs]
  const out = []
  let conflict = false
  const regions = []
  const stable = (from, to) => {
    if (to > from) {
      out.push(...base.slice(from, to))
      regions.push(`stable ${to - from}`)
    }
  }
  let pos = 0, k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(pos, rs)
    pos = re
    const baseLines = base.slice(rs, re)
    const rep = sides.map((s, idx) => {
      const cs = group.filter(c => c.side === idx)
      if (!cs.length) return baseLines
      const minB = Math.min(...cs.map(c => c.bs)), maxB = Math.max(...cs.map(c => c.be))
      const start = Math.min(...cs.map(c => c.ss)) - (minB - rs)
      const end = Math.max(...cs.map(c => c.se)) + (re - maxB)
      return s.slice(start, end)
    })
    const [m, t] = rep
    let res, label
    if (group.length === 1) {
      res = rep[group[0].side]; label = group[0].side ? 'theirs' : 'mine'
    } else if (eq(m, t)) { res = m; label = 'both' }
    else if (eq(m, baseLines)) { res = t; label = 'theirs' }
    else if (eq(t, baseLines)) { res = m; label = 'mine' }
    else label = null
    if (label) {
      out.push(...res)
      regions.push(`${label} ${res.length}`)
    } else {
      conflict = true
      regions.push(`conflict mine=${m.length} base=${baseLines.length} theirs=${t.length}`)
      out.push('<<<<<<< mine', ...m)
      if (mode === 'merge') out.push('||||||| base', ...baseLines)
      out.push('=======', ...t, '>>>>>>> theirs')
    }
  }
  stable(pos, base.length)
  return { out: mode === 'regions' ? regions : out, conflict }
}
