export class ParseError extends Error {}

const NAME_RE = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?\d+(?:_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(?:_\d+)*(?:\.\d+(?:_\d+)*)?(?:[eE][+-]?\d+(?:_\d+)*)?$/

const newTable = () => ({ t: 'table', m: new Map(), header: false })

function fail(msg) {
  throw new ParseError(msg)
}

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  ws() {
    while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++
  }
  // true when at end of line or at a comment
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  name() {
    const c = this.s[this.i]
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (this.i < this.s.length && NAME_RE.test(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] !== '.') {
        this.i = save
        return parts
      }
      this.i++
      this.ws()
      parts.push(this.name())
    }
  }
  basic() {
    this.i++
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        const e = this.s[this.i + 1]
        if (e === undefined) fail('unterminated string')
        this.i += 2
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
        } else {
          const cp = String.fromCodePoint(this.s.codePointAt(this.i - 1))
          fail('invalid escape \\' + cp)
        }
        continue
      }
      out += c
      this.i++
    }
  }
  literal() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return v
  }
  value(prefix) {
    const c = this.s[this.i]
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < this.s.length && !/[ \t,\]};]/.test(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === '') fail('expected a value')
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    if (INT_RE.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (FLOAT_RE.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }
  array(prefix) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.s[this.i] === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      }
      items.push(this.value(prefix))
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c !== ']') fail('trailing text after a value')
    }
  }
  inline(prefix) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.s[this.i] === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      if (this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value(prefix.concat(keys))
      assign(tbl, prefix, keys, v)
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === '}') {
        this.i++
        return tbl
      } else fail('trailing text after a value')
    }
  }
}

function step(node, key, path) {
  // descend into node.m[key] for a walk-through; create when absent
  let next = node.m.get(key)
  if (next === undefined) {
    next = newTable()
    node.m.set(key, next)
  } else if (next.t === 'array' && next.aot) {
    next = next.items[next.items.length - 1]
  } else if (next.t !== 'table') {
    fail(path.join('.') + ' is not a table')
  }
  return next
}

function assign(root, prefix, keys, v) {
  let cur = root
  for (let k = 0; k < keys.length - 1; k++) cur = step(cur, keys[k], prefix.concat(keys.slice(0, k + 1)))
  const last = keys[keys.length - 1]
  if (cur.m.has(last)) fail('key ' + prefix.concat(keys).join('.') + ' is defined twice')
  cur.m.set(last, v)
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const L = new Line(lines[n])
      L.ws()
      if (L.atEnd()) continue
      if (L.s[L.i] === '[') {
        const dbl = L.s[L.i + 1] === '['
        L.i += dbl ? 2 : 1
        L.ws()
        const keys = L.dotted()
        L.ws()
        if (L.atEnd()) fail('unterminated table header')
        if (L.s[L.i] !== ']') fail('unterminated table header')
        L.i++
        if (dbl) {
          if (L.s[L.i] !== ']') fail('unterminated table header')
          L.i++
        }
        L.ws()
        if (!L.atEnd()) fail('trailing text after a table header')
        let node = root
        for (let k = 0; k < keys.length - 1; k++) node = step(node, keys[k], keys.slice(0, k + 1))
        const last = keys[keys.length - 1]
        const p = keys.join('.')
        const ex = node.m.get(last)
        if (dbl) {
          const fresh = newTable()
          fresh.header = true
          if (ex === undefined) node.m.set(last, { t: 'array', items: [fresh], aot: true })
          else if (ex.t === 'array' && ex.aot) ex.items.push(fresh)
          else fail(p + ' is not an array of tables')
          cur = fresh
        } else {
          if (ex === undefined) {
            const t = newTable()
            t.header = true
            node.m.set(last, t)
            cur = t
          } else if (ex.t === 'table') {
            if (ex.header) fail('table ' + p + ' is defined twice')
            ex.header = true
            cur = ex
          } else fail(p + ' is not a table')
        }
        curPath = keys
      } else {
        const keys = L.dotted()
        L.ws()
        if (L.s[L.i] !== '=') fail('expected key = value')
        L.i++
        L.ws()
        const v = L.value(curPath.concat(keys))
