  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (names !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    names = []
    for (const c of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(c)) fail(`error: line ${n}: invalid candidate name ${c}`)
      if (known.has(c)) fail(`error: line ${n}: candidate ${c} is declared twice`)
      known.add(c)
      names.push(c)
    }
  } else if (t[0] === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const c of t.slice(2)) {
      if (!known.has(c)) fail(`error: line ${n}: unknown candidate ${c}`)
      if (seen.has(c)) fail(`error: line ${n}: candidate ${c} is repeated`)
      seen.add(c)
