/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const WORD = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function num(field, text, least) {
  if (!UINT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function makeBucket(name, capacity, refill, per) {
  // Tokens are stored scaled by `per`, so fractions stay exact.
  const cap = capacity * per
  return {
    name,
    fresh() { return { units: cap, last: null } },
    advance(s, tick) {
      if (s.last === null) { s.last = tick; return }
      s.units += refill * (tick - s.last)
      if (s.units > cap) s.units = cap
      s.last = tick
    },
    allows(s) { return s.units >= per },
    record(s) { s.units -= per },
  }
}

function makeWindow(name, limit, span) {
  return {
    name,
    fresh() { return { ticks: [] } },
    advance(s, tick) {
      const cut = tick - span
      s.ticks = s.ticks.filter((t) => t > cut)
    },
    allows(s) { return BigInt(s.ticks.length) < limit },
    record(s, tick) { s.ticks.push(tick) },
  }
}

function run(text) {
  let lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const stats = new Map()
  const out = []
  let started = false
  let prev = null
  let allowed = 0
  let denied = 0

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    try {
      const d = f[0]
      if (d !== 'bucket' && d !== 'window' && d !== 'route' && d !== 'event') {
        throw new Fail(`unknown directive ${d}`)
      }
      if (d !== 'event' && started) throw new Fail('declarations must come before the first event')
      if (d === 'bucket') {
        if (f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!WORD.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const c = num('capacity', f[2], 1)
        const r = num('refill', f[3], 0)
        const p = num('per', f[4], 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], makeBucket(f[1], c, r, p))
      } else if (d === 'window') {
        if (f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!WORD.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const l = num('limit', f[2], 0)
